    # Condition 2: For any two distinct elements, there exists a third element that divides their product
    for pair in combinations(U, 2):
        x, y = pair
        product = x * y
        found_divisor = False

        # Check all remaining elements
        remaining = [z for z in U if z != x and z != y]

        for z in remaining:
            if product % z == 0:
